// Simplified shadow mapping logic in a URP shader
// This runs for every pixel of every object

// 1. Get the pixel's position in light space
float4 shadowCoord = TransformWorldToShadowCoord(worldPos);

// 2. Sample the shadow map
float shadowMapDepth = SampleShadowMap(shadowCoord.xy);

// 3. Compare: is this pixel farther from light than shadow map says?
float pixelDepth = shadowCoord.z;

if (pixelDepth > shadowMapDepth + bias)
{
    // Something is blocking the light → SHADOW
    shadowAttenuation = 0.0;
}
else
{
    // Light reaches this pixel → LIT
    shadowAttenuation = 1.0;
}

// 4. Apply to lighting
float3 litColor = albedo * lightColor * shadowAttenuation;

